mapper.update:
UPDATE sw_im_bot SET takeover_config_cipher=#{cipher}
WHERE id=#{bot.id} AND identity_mode='USER' AND enabled=1 AND config_version=#{bot.configVersion}
 AND owner_node=#{node} AND owner_version=#{version} AND lease_until > CURRENT_TIMESTAMP(6)
 AND takeover_config_cipher=#{previous}

UPDATE sw_im_bot SET enabled=0,connection_state='ERROR',last_error=#{error},config_version=config_version+1
WHERE id=#{bot.id} AND identity_mode='USER' AND config_version=#{bot.configVersion}
 AND owner_node=#{node} AND owner_version=#{version} AND lease_until > CURRENT_TIMESTAMP(6)
